<?php session_start(); require_once __DIR__.'/../../config/db_connect.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['full_name']??'');$email=filter_input(INPUT_POST,'email',FILTER_VALIDATE_EMAIL);$p=$_POST['password']??'';$c=$_POST['confirm_password']??''; if(!$name||!$email||strlen($p)<8||$p!==$c)$error='Please provide valid details and matching passwords (minimum 8 characters).'; else {try{$q=$pdo->prepare("INSERT INTO managers(full_name,email,password) VALUES(?,?,?)");$q->execute([$name,$email,password_hash($p,PASSWORD_DEFAULT)]);header('Location: login.php');exit;}catch(PDOException $e){$error='Unable to register. The email may already be registered.';}}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manager Registration</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="section"><div class="container"><div class="card"><h1>Manager Registration</h1><?php if($error):?><div class="alert"><?=htmlspecialchars($error)?></div><?php endif;?><form class="form" method="post"><input name="full_name" required placeholder="Full name"><input name="email" type="email" required placeholder="Email"><input name="password" type="password" required placeholder="Password"><input name="confirm_password" type="password" required placeholder="Confirm password"><button class="btn btn-primary">Register</button></form></div></div></main></body></html>